If you want to **add animation in JavaScript** by **just copy-pasting code**, here are **3 super simple ways** to do that:

---

### ✅ 1. **Using CSS Animation + JS (Basic Trigger)**
Just paste this in your HTML file. It adds a button with a box that animates when clicked.

```html
<!DOCTYPE html>
<html>
<head>
  <style>
    .box {
      width: 100px;
      height: 100px;
      background-color: red;
      position: relative;
      transition: transform 1s ease;
    }

    .move {
      transform: translateX(200px);
    }
  </style>
</head>
<body>

<div class="box" id="box"></div>
<button onclick="animateBox()">Animate</button>

<script>
  function animateBox() {
    document.getElementById("box").classList.toggle("move");
  }
</script>

</body>
</html>
```

---

### ✅ 2. **Using JavaScript-only Animation (No CSS)**
Copy-paste this to create a box that moves smoothly using `setInterval`:

```html
<!DOCTYPE html>
<html>
<body>

<div id="box" style="width:100px;height:100px;background:red;position:absolute;"></div>
<button onclick="moveBox()">Start Animation</button>

<script>
function moveBox() {
  let box = document.getElementById("box");
  let pos = 0;
  let id = setInterval(frame, 5);

  function frame() {
    if (pos == 350) {
      clearInterval(id);
    } else {
      pos++;
      box.style.left = pos + "px";
    }
  }
}
</script>

</body>
</html>
```

---

### ✅ 3. **Using `requestAnimationFrame` (Smoothest way)**
Modern and smoother alternative using the browser’s rendering loop:

```html
<!DOCTYPE html>
<html>
<body>

<div id="circle" style="width:50px;height:50px;background:blue;border-radius:50%;position:absolute;"></div>
<button onclick="animate()">Start Smooth Animation</button>

<script>
function animate() {
  const elem = document.getElementById("circle");
  let pos = 0;

  function move() {
    if (pos < 300) {
      pos += 2;
      elem.style.left = pos + "px";
      requestAnimationFrame(move);
    }
  }

  move();
}
</script>

</body>
</html>
```

---

